// Parse Google Document AI response
const items = $input.all();
const results = [];

for (const item of items) {
  const response = item.json;
  const document = response.document || {};
  const entities = document.entities || [];

  // Map entity types to invoice fields
  const entityMap = {
    vendor: ['vendor', 'supplier', 'seller', 'from', 'receiver'],
    invoice_date: ['date', 'invoice_date', 'invoice date', 'issue_date'],
    invoice_number: ['invoice_number', 'invoice_id', 'number', 'no', 'invoice_no'],
    amount: ['amount', 'total', 'total_amount', 'grand_total', 'nominal', 'balance_due']
  };

  const extracted = {
    vendor: null,
    invoice_date: null,
    invoice_number: null,
    amount: null,
    confidence_scores: {
      vendor: 0.0,
      invoice_date: 0.0,
      invoice_number: 0.0,
      amount: 0.0,
      overall: 0.0
    }
  };

  const confidences = [];

  for (const entity of entities) {
    const entityType = (entity.type || '').toLowerCase();
    const mentionText = (entity.mentionText || '').trim();
    const confidence = entity.confidence || 0.0;

    for (const [field, keywords] of Object.entries(entityMap)) {
      if (keywords.some(kw => entityType.includes(kw))) {
        extracted[field] = mentionText;
        extracted.confidence_scores[field] = confidence;
        confidences.push(confidence);
        break;
      }
    }
  }

  // Calculate overall confidence
  extracted.confidence_scores.overall =
    confidences.length > 0
      ? confidences.reduce((a, b) => a + b, 0) / confidences.length
      : 0.0;

  // Source detection: Gmail has 'attachments', Drive has 'id' and 'mimeType'
  const source = (item.json.attachments || item.json.mimeType) ? 'Gmail' : 'Drive';
  const driveFileId = item.json.id || (item.json.attachments && item.json.attachments[0] ? item.json.attachments[0].id : '');
  const driveFileLink = driveFileId
    ? 'https://drive.google.com/file/d/' + driveFileId + '/view'
    : '';

  results.push({
    json: {
      vendor: extracted.vendor,
      invoice_date: extracted.invoice_date,
      invoice_number: extracted.invoice_number,
      amount: extracted.amount,
      confidence_scores: extracted.confidence_scores,
      overall_confidence: extracted.confidence_scores.overall,
      source: source,
      drive_file_id: driveFileId,
      drive_file_link: driveFileLink
    }
  });
}

return results;

// Check for duplicate invoice using composite key
const items = $input.all();
const results = [];

for (const item of items) {
  const invoice = item.json;

  // Build composite key (case-insensitive, trimmed)
  const vendor = (invoice.vendor || '').trim().toLowerCase();
  const invoiceNumber = (invoice.invoice_number || '').trim().toLowerCase();
  const invoiceDate = (invoice.invoice_date || '').trim();
  const amount = String(invoice.amount || '').trim();

  const newKey = vendor + '|' + invoiceNumber + '|' + invoiceDate + '|' + amount;

  // Read existing invoices from previous node
  const existingRows = $input.first().json.data || [];
  let isDuplicate = false;
  let matchedRowIndex = -1;

  for (let i = 0; i < existingRows.length; i++) {
    const row = existingRows[i];
    const existVendor = (row.vendor || '').trim().toLowerCase();
    const existNumber = (row.invoice_number || '').trim().toLowerCase();
    const existDate = (row.invoice_date || '').trim();
    const existAmount = String(row.amount || '').trim();

    const existKey = existVendor + '|' + existNumber + '|' + existDate + '|' + existAmount;

    if (existKey === newKey && existKey !== '|||') {
      isDuplicate = true;
      matchedRowIndex = i;
      break;
    }
  }

  results.push({
    json: {
      ...invoice,
      is_duplicate: isDuplicate,
      matched_row_index: matchedRowIndex,
      status: isDuplicate ? 'Duplicate' : 'Pending Approval'
    }
  });
}

return results;

// Build invoice row for Google Sheets
const items = $input.all();
const results = [];

for (const item of items) {
  const inv = item.json;
  const now = new Date().toISOString();

  // Generate UUID v4
  const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });

  results.push({
    json: {
      invoice_id: uuid,
      received_at: now,
      vendor: inv.vendor || '',
      invoice_date: inv.invoice_date || '',
      invoice_number: inv.invoice_number || '',
      amount: inv.amount || 0,
      status: inv.status || 'Pending Approval',
      confidence: inv.overall_confidence || 0,
      drive_file_id: inv.drive_file_id || '',
      drive_file_link: inv.drive_file_link || '',
      source: inv.source || 'Drive',
      approved_at: '',
      approved_by: '',
      rejected_at: '',
      reject_reason: '',
      reminder_count: 0,
      last_reminder_at: '',
      created_at: now,
      updated_at: now
    }
  });
}

return results;

// Build duplicate row for Google Sheets
const items = $input.all();
const results = [];

for (const item of items) {
  const inv = item.json;
  const now = new Date().toISOString();

  results.push({
    json: {
      invoice_id: 'DUPLICATE-' + Date.now(),
      received_at: now,
      vendor: inv.vendor || '',
      invoice_date: inv.invoice_date || '',
      invoice_number: inv.invoice_number || '',
      amount: inv.amount || 0,
      status: 'Duplicate',
      confidence: inv.overall_confidence || 0,
      drive_file_id: inv.drive_file_id || '',
      drive_file_link: inv.drive_file_link || '',
      source: inv.source || 'Drive',
      approved_at: '',
      approved_by: '',
      rejected_at: '',
      reject_reason: 'Duplicate of existing invoice (row ' + (inv.matched_row_index + 1) + ')',
      reminder_count: 0,
      last_reminder_at: '',
      created_at: now,
      updated_at: now
    }
  });
}

return results;

// Send Telegram notification to Owner (only for new invoices, not duplicates)
const items = $input.all();
const results = [];

for (const item of items) {
  const inv = item.json;

  // Format amount as Indonesian Rupiah
  const amountNum = Number(inv.amount) || 0;
  const amountFormatted = 'Rp ' + amountNum.toLocaleString('id-ID');

  // Confidence as percentage
  const confidencePct = Math.round((inv.confidence || 0) * 100);

  // Build message
  const message =
    '📄 <b>Invoice Baru Masuk</b>\n\n' +
    '🏢 Vendor: ' + (inv.vendor || '-') + '\n' +
    '📅 Tanggal: ' + (inv.invoice_date || '-') + '\n' +
    '🔢 No. Invoice: ' + (inv.invoice_number || '-') + '\n' +
    '💰 Nominal: ' + amountFormatted + '\n' +
    '🎯 Confidence: ' + confidencePct + '%\n\n' +
    '📎 <a href="' + (inv.drive_file_link || '#') + '">Lihat File</a>\n\n' +
    'Status: <b>' + (inv.status || 'Pending Approval') + '</b>';

  results.push({
    json: {
      chatId: '={{$env.TELEGRAM_OWNER_CHAT_ID}}',
      text: message,
      parseMode: 'HTML',
      invoice_id: inv.invoice_id,
      vendor: inv.vendor,
      amount: amountFormatted
    }
  });
}

return results;

// Low Confidence — log for manual review
const items = $input.all();
const results = [];

for (const item of items) {
  const inv = item.json;
  const now = new Date().toISOString();

  console.log('[LOW CONFIDENCE] invoice_id=unknown confidence=' + inv.overall_confidence + ' vendor=' + inv.vendor);

  results.push({
    json: {
      invoice_id: 'LOWCONF-' + Date.now(),
      received_at: now,
      vendor: inv.vendor || 'UNKNOWN',
      invoice_date: inv.invoice_date || '',
      invoice_number: inv.invoice_number || '',
      amount: inv.amount || 0,
      status: 'Low Confidence',
      confidence: inv.overall_confidence || 0,
      drive_file_id: inv.drive_file_id || '',
      drive_file_link: inv.drive_file_link || '',
      source: inv.source || 'Drive',
      approved_at: '',
      approved_by: '',
      rejected_at: '',
      reject_reason: 'OCR confidence below 85% threshold -- manual review required',
      reminder_count: 0,
      last_reminder_at: '',
      created_at: now,
      updated_at: now
    }
  });
}

return results;

